#include <stdio.h>
#define MAX 100
int queue[MAX], front=-1, rear=-1;
void enqueue(int val){
    if(rear==MAX-1){printf("Overflow\n");return;}
    if(front==-1)front=0;
    queue[++rear]=val;
}
int dequeue(){
    if(front==-1||front>rear){printf("Underflow\n");return -1;}
    return queue[front++];
}
int main(){
    enqueue(10);enqueue(20);enqueue(30);
    printf("%d\n",dequeue());
    printf("Front: %d\n",queue[front]);
    return 0;
}

