#include <iostream>
using namespace std;

class CircularQueue {
    int *arr, front, rear, cap, sz;
public:
    CircularQueue(int c): cap(c), front(0), rear(0), sz(0) { arr = new int[c]; }
    bool enqueue(int val) {
        if(sz==cap) return false;
        arr[rear]=val; rear=(rear+1)%cap; sz++; return true;
    }
    int dequeue() {
        if(sz==0) return -1;
        int val=arr[front]; front=(front+1)%cap; sz--; return val;
    }
    int peek() { return sz>0?arr[front]:-1; }
};

int main() {
    CircularQueue cq(3);
    cq.enqueue(1); cq.enqueue(2); cq.enqueue(3);
    cout<<cq.dequeue()<<endl;
    cq.enqueue(4);
    cout<<cq.peek()<<endl;
    return 0;
}

